(function(root,factory){const api=factory(root);if(typeof module==='object'&&module.exports)module.exports=api;if(typeof globalThis!=='undefined')globalThis.KeywordOSCompetitorTrendsTest=api;if(root){root.KeywordOSCompetitorTrends=api;api.start?.();}})(typeof window!=='undefined'?window:null,function(root){
'use strict';
const STORAGE_KEY='keywordos_growth_competitor_v1';
function competitorTrendSeries(rows=[]){const groups=new Map();for(const row of rows){const asin=String(row?.asin||'').trim(),date=String(row?.date||'').slice(0,10);if(!asin||!/^\d{4}-\d{2}-\d{2}$/.test(date))continue;if(!groups.has(asin))groups.set(asin,[]);groups.get(asin).push({...row,asin,date});}return[...groups].map(([asin,history])=>({asin,points:[...history].sort((a,b)=>a.date.localeCompare(b.date))})).filter(item=>item.points.length>=2).sort((a,b)=>b.points.length-a.points.length||a.asin.localeCompare(b.asin));}
function competitorSeasonality(rows=[]){const groups=new Map();for(const row of rows){const date=String(row?.date||'').slice(0,10),asin=String(row?.asin||'').trim();if(!asin||!/^\d{4}-\d{2}-\d{2}$/.test(date))continue;const month=date.slice(5,7),year=date.slice(0,4),key=`${asin}|${month}`,current=groups.get(key)||{asin,month,years:new Set(),rows:[]};current.years.add(year);current.rows.push(row);groups.set(key,current);}const average=(rows,key)=>{const values=rows.map(row=>Number(row[key])).filter(value=>Number.isFinite(value)&&value>0);return values.length?values.reduce((sum,value)=>sum+value,0)/values.length:null;};return[...groups.values()].filter(item=>item.years.size>=2).map(item=>({asin:item.asin,month:item.month,years:[...item.years].sort(),snapshots:item.rows.length,price:average(item.rows,'price'),bsr:average(item.rows,'bsr'),reviewCount:average(item.rows,'reviewCount')})).sort((a,b)=>a.asin.localeCompare(b.asin)||a.month.localeCompare(b.month));}
function chartPoints(points,key,width=300,height=92){const usable=points.filter(point=>{const value=Number(point[key]);return Number.isFinite(value)&&value>0;});if(usable.length<2)return null;const min=Math.min(...usable.map(point=>Number(point[key]))),max=Math.max(...usable.map(point=>Number(point[key]))),span=max-min||1;return usable.map((point,index)=>({date:point.date,value:Number(point[key]),x:8+(width-16)*(usable.length===1?0:index/(usable.length-1)),y:8+(height-16)*(1-(Number(point[key])-min)/span)}));}
function miniChart(points,key,label,format=value=>String(value)){const plotted=chartPoints(points,key);if(!plotted)return`<div class="muted">${label}: not enough imported values</div>`;const path=plotted.map((point,index)=>`${index?'L':'M'} ${point.x.toFixed(1)} ${point.y.toFixed(1)}`).join(' '),first=plotted[0],last=plotted.at(-1);return`<div><b>${label}</b><svg viewBox="0 0 300 92" role="img" aria-label="${label} trend from ${first.date} to ${last.date}" style="display:block;width:100%;max-width:360px;height:92px"><path d="${path}" fill="none" stroke="currentColor" stroke-width="2"></path>${plotted.map(point=>`<circle cx="${point.x.toFixed(1)}" cy="${point.y.toFixed(1)}" r="2.5" fill="currentColor"><title>${point.date}: ${format(point.value)}</title></circle>`).join('')}</svg><small>${first.date} ${format(first.value)} → ${last.date} ${format(last.value)}</small></div>`;}
function escapeHtml(value){return String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));}
function renderTrendPanel(rows=[]){const series=competitorTrendSeries(rows),seasonality=competitorSeasonality(rows);if(!series.length)return'<div id="competitor-trend-panel" class="notice-banner top-gap">Trend charts unavailable: import at least two dated snapshots for the same ASIN.</div>';const cards=series.slice(0,10).map(item=>`<div class="card-body"><h3>${escapeHtml(item.asin)}</h3><small>${item.points.length} dated snapshots · ${escapeHtml(item.points[0].date)} → ${escapeHtml(item.points.at(-1).date)}</small><div class="growth-kpis top-gap">${miniChart(item.points,'price','Price',value=>'$'+value.toFixed(2))}${miniChart(item.points,'bsr','BSR',value=>Math.round(value).toLocaleString('en-US'))}${miniChart(item.points,'reviewCount','Reviews',value=>Math.round(value).toLocaleString('en-US'))}</div></div>`).join('');const seasonal=seasonality.length?`<div class="card-body"><h3>Repeated-calendar-month evidence</h3><small>Shown only when the same ASIN has imported snapshots in the same calendar month across 2+ years. Averages summarize imported observations; they are not a forecast.</small></div><div class="table-scroll"><table class="data-table"><thead><tr><th class="left">ASIN</th><th class="left">Month</th><th class="left">Years</th><th class="left">Snapshots</th><th class="left">Avg price</th><th class="left">Avg BSR</th><th class="left">Avg reviews</th></tr></thead><tbody>${seasonality.map(item=>`<tr><td>${escapeHtml(item.asin)}</td><td>${escapeHtml(item.month)}</td><td>${escapeHtml(item.years.join(', '))}</td><td>${item.snapshots}</td><td>${item.price==null?'—':'$'+item.price.toFixed(2)}</td><td>${item.bsr==null?'—':Math.round(item.bsr).toLocaleString('en-US')}</td><td>${item.reviewCount==null?'—':Math.round(item.reviewCount).toLocaleString('en-US')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="card-body"><span class="muted">Seasonality evidence unavailable: no ASIN has snapshots from the same calendar month across at least two years. KeywordOS does not infer seasonality from a single-year series.</span></div>';return`<div id="competitor-trend-panel" class="card top-gap"><div class="card-head"><div class="card-title"><h3>Snapshot trends & seasonality evidence</h3><small>Charts use only explicit imported snapshot dates and values. Missing metrics stay unavailable.</small></div></div>${cards}${seasonal}</div>`;}
async function readRows(){try{const record=await root?.KeywordOSDatasetRegistry?.get?.('competitor','store-a');if(Array.isArray(record?.rows)&&record.rows.length)return record.rows;}catch{}try{const rows=JSON.parse(root?.localStorage?.getItem(STORAGE_KEY)||'[]');return Array.isArray(rows)?rows:[];}catch{return[];}}
let scheduled=false;async function inject(){scheduled=false;if(!root?.document||!String(root.location?.hash||'').startsWith('#page=competitor-snapshots'))return;const content=root.document.getElementById('content');if(!content||content.querySelector('#competitor-trend-panel'))return;const rows=await readRows();if(!String(root.location?.hash||'').startsWith('#page=competitor-snapshots')||content.querySelector('#competitor-trend-panel'))return;content.insertAdjacentHTML('beforeend',renderTrendPanel(rows));}
function schedule(){if(scheduled)return;scheduled=true;setTimeout(inject,0);}
function start(){if(!root?.document)return;const boot=()=>{const content=root.document.getElementById('content');if(!content)return;schedule();new MutationObserver(schedule).observe(content,{childList:true,subtree:false});root.addEventListener('hashchange',schedule);};root.document.readyState==='loading'?root.document.addEventListener('DOMContentLoaded',boot,{once:true}):boot();}
return{STORAGE_KEY,competitorTrendSeries,competitorSeasonality,chartPoints,renderTrendPanel,start};
});
